[TFMDescription("An Expression used to get the logistics postal address")]
class TFMExpressionsPostalAddress extends TFMExpressions
{

}

Method.Source:
public str processExpressionCommon(Common _common)
{
    DictTable dt = new DictTable(_common.tableId);
    FieldId   fieldId  = (dt != null ? dt.fieldName2Id(identifierStr(LogisticsPostalAddressRecId)) : 0);

    return this.processExpressionValue(fieldId ? _common.(fieldId) : '');
}
